/** What this MetroPlat tells the harness projection: the records it reads, the settlement it
 *  settles into, and how a session reaches this machine's one MetroPlat node. A session is a
 *  client: its MCP face is the bridge to the running node (METROPLAT_NODE_CLIENT_ENV names the
 *  machine client's credentials), never a MetroPlat of its own. No hooks are projected until the
 *  node admits hook events itself: a hook that loads MetroPlat per event is a second instance. */
function claudeHarnessHost(binding) {
  const bridge = fileURLToPath(import.meta.resolve("@red-cup-engineering/mcp-engineering-services-section/scripts/bridge-mcp-server"));
  const clientEnvironment = () => process.env.METROPLAT_NODE_CLIENT_ENV ?? path.join(homedir(), ".config", "561-group", "ops-mcp-client.env");
  return {
    harness: "claude",
    get agencyRoot() { return agencyRootOf(binding); },
    get repoRoot() { return path.dirname(agencyRootOf(binding)); },
    dataRoot: binding.dataRoot,
    mcpServers: () => ({
      metroplat: { type: "stdio", command: "node", args: [`--env-file=${clientEnvironment()}`, bridge] },
    }),
    standing: () => fiber(consolidateAt(binding.dataRoot)),
  };
}

/** Work allocation's two resolvers, by default read from this MetroPlat's own records: office,
 *  duty, work and skill authority from the live agency registry, and model characters from the
 *  harness carriers admitted in its settlement. A host's own configuration overrides either. */
function defaultWorkOptions(binding) {
  let authority;
  return {
    resolveAgencyWorkAuthority: (allocation) => (authority ??= firmPoolAuthorityResolver({ firmPoolRoot: agencyRootOf(binding) }))(allocation),
    resolveModelCharacter: (character) => harnessModelCharacterResolver(binding)(character),
  };
}

/**
 * Every service-visible module family: the package's own module families plus
 * the host-boundary families each service process contributes as a mesh member.
 *
 * `binding` is required: there is no unbound mode: every state-cut derivation
 * needs a real data root to read against, so callers with no explicit root
 * pass the package root, same as `defaultFilesystemBinding` everywhere else in
 * this package.
 */

/** Application and integration sources record claims. This is a bootstrap
 * collection, not a runtime capability table: the runtime receives only the
 * resulting journal statements and recomputes their standing. */
function* serviceSources(
  binding,
  operationSource = () => [],
  trustedOperationSources = [],
  workOptions = {},
  sourceSet = () => [],
) {
  for (const [module, operations] of Object.entries(builtinOperationModules)) yield Object.freeze({ module, operations });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/offices", operations: officeOperations(binding, sourceSet) });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/metroplex", operations: metroplexOperations(binding, operationSource) });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/l-space", operations: lSpaceOperations() });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/claude-harness", operations: claudeHarnessOperations(claudeHarnessHost(binding)) });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/codex-harness", operations: codexTaskOperations({
    dataRoot: binding.dataRoot, cwd: process.env.METROPLAT_CODEX_WORKSPACE ?? path.dirname(agencyRootOf(binding)),
    characterName: process.env.METROPLAT_CODEX_CHARACTER_NAME ?? "bare-cedar-fog-codex",
    ...(process.env.METROPLAT_CODEX_MODEL ? { model: process.env.METROPLAT_CODEX_MODEL } : {}),
    ...(process.env.METROPLAT_CODEX_BIN ? { codex: process.env.METROPLAT_CODEX_BIN } : {}),
  }) });
  for (const source of trustedOperationSources) yield Object.freeze({ module: source.module, operations: Object.freeze([...source.operations]) });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/integrations/filesystem", operations: filesystemOperations });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/markdown-files", operations: markdownFileWorkbenchOperations({ ...binding, resources: { readAtRoot, writeAtRoot } }) });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/arc42-sad", operations: arc42SadWorkbenchOperations(binding) });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/specifications", operations: specificationWorkbenchOperations(binding) });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/claude-fleet", operations: claudeFleetOperations(binding) });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/claude-sessions", operations: claudeSessionOperations(binding) });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/agent-coordination", operations: agentCoordinationOperations(binding) });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/claim-sessions", operations: claimSessionOperations(binding) });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/codex-sessions", operations: codexSessionOperations(binding) });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/openai-pricing", operations: openAIPricingOperations(binding) });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/ledger", operations: ledgerReportOperations() });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/ledger-maintenance", operations: ledgerMaintenanceOperations({
    settlementsOf: (enterprise, since) => enterpriseStore(binding).read("settlement", { enterprise }).filter((record) => !since || String(record.recordedAt) >= since),
  }) });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/energy-accounting", operations: energyAccountingOperations() });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/marsh", operations: marshResourceOperations });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/marsh-hive-engine", operations: marshHiveEngineResourceOperations });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/agent-token-usage", operations: agentTokenUsageOperations(binding) });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/conurbation", operations: conurbationOperations(binding) });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/work-coordination", operations: workCoordinationOperations(binding, { ...defaultWorkOptions(binding), ...workOptions }) });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/journal", operations: feedReadoutOperations(binding) });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/proof-health", operations: proofHealthOperations(binding, operationSource) });
  yield Object.freeze({ module: "@red-cup-engineering/metroplat/attention-allocation", operations: attentionAllocationOperations() });
